import sys

def xor_range(x, y):
    def xor_to(n):
        if n == 0:
            return 0
        patterns = [0, 1, 3, 0]
        return patterns[n % 4]

    return xor_to(y) ^ xor_to(x - 1)

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    l = int(input[1], 2)
    r = int(input[2], 2)

    max_xor = 0
    for i in range(n + 1):
        mask = (1 << i) - 1
        start = (l & ~mask) | mask
        end = (r & ~mask)
        if start <= end:
            max_xor = max(max_xor, xor_range(start, end))

    print(bin(max_xor)[2:])

if __name__ == "__main__":
    main()
